def styled_icon(name, size=20, color="currentColor", bg_color="#f3f4f6", padding="6px", border_radius="6px"):
    """
    Genera un icono SVG con estilo de fondo

    Args:
        name: Nombre del icono
        size: Tamaño del icono
        color: Color del icono
        bg_color: Color de fondo
        padding: Padding alrededor del icono
        border_radius: Radio del borde

    Returns:
        HTML con icono estilizado
    """
    return f'''<span style="display:inline-flex; align-items:center; justify-content:center; background:{bg_color}; padding:{padding}; border-radius:{border_radius}; margin-right:8px; vertical-align:middle;">{icon(name, size, color)}</span>'''


# Estilos CSS para los iconos (se puede incluir una vez en la página)
ICON_STYLES = """
<style>
.icon {
    display: inline-block;
    vertical-align: middle;
    flex-shrink: 0;
}

.icon-box {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.icon-spin {
    animation: icon-spin 1s linear infinite;
}

@keyframes icon-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}
</style>
"""
